<?php require 'config.php'; $id=(int)($_GET['id']??0); $student=['name'=>'','roll_number'=>'','email'=>'','course'=>'']; if($id){$st=$conn->prepare('SELECT name,roll_number,email,course FROM students WHERE id=?');$st->bind_param('i',$id);$st->execute();$student=$st->get_result()->fetch_assoc()?:$student;} ?>
<!doctype html><html><head><meta charset="utf-8"><title>Student Form</title><link rel="stylesheet" href="style.css"></head><body><div class="wrap form"><h1><?=$id?'Edit':'Add'?> Student</h1><form action="save.php" method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=$id?>"><label>Name<input required name="name" value="<?=htmlspecialchars($student['name'])?>"></label><label>Roll Number<input required name="roll_number" value="<?=htmlspecialchars($student['roll_number'])?>"></label><label>Email<input type="email" name="email" value="<?=htmlspecialchars($student['email'])?>"></label><label>Course<input required name="course" value="<?=htmlspecialchars($student['course'])?>"></label><label>Profile / ID / Certificate<input type="file" name="document" accept=".jpg,.jpeg,.png,.pdf"></label><button class="btn" type="submit">Save Student</button> <a href="index.php">Cancel</a></form></div></body></html>
